    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.401" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/analyze.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

void CollectAll(BaseNode node, List<Error> errors, List<Warning> warnings)
{
    if (node is Error e) errors.Add(e);
    if (node is Warning w) warnings.Add(w);
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            CollectAll(child, errors, warnings);
}

var errors = new List<Error>();
var warnings = new List<Warning>();
CollectAll(build, errors, warnings);

Console.WriteLine($"=== BUILD SUCCEEDED: {build.Succeeded} ===");
Console.WriteLine($"\n=== ERRORS ({errors.Count}) ===");
foreach (var err in errors)
{
    var project = "";
    var p = err.Parent;
    while (p != null)
    {
        if (p is Project proj) { project = proj.Name; break; }
        if (p is Target tgt) { /* keep going */ }
        p = (p as TreeNode)?.Parent as BaseNode;
    }
    Console.WriteLine($"\n[Project: {project}]");
    Console.WriteLine($"  Code: {err.Code}");
    Console.WriteLine($"  File: {err.File}:{err.LineNumber}");
    Console.WriteLine($"  Message: {err.Text}");
}

Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
foreach (var w in warnings.Take(30))
{
    Console.WriteLine($"  [{w.Code}] {w.File}:{w.LineNumber} - {w.Text}");
}
if (warnings.Count > 30) Console.WriteLine($"  ... and {warnings.Count - 30} more warnings");
CSHARP

