cat > /tmp/analyze2.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Find all projects and their dependency relationships
void FindProjects(BaseNode node, List<Project> projects)
{
    if (node is Project p) projects.Add(p);
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            FindProjects(child, projects);
}

void FindItems(BaseNode node, string name, List<string> items)
{
    if (node is AddItem ai && ai.Name == name)
        foreach (var child in ai.Children)
            if (child is Item item) items.Add(item.Text);
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            FindItems(child, name, items);
}

var projects = new List<Project>();
FindProjects(build, projects);

Console.WriteLine("=== PROJECTS IN BUILD ===");
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} (Succeeded: {p.Succeeded})");
    var refs = new List<string>();
    FindItems(p, "PackageReference", refs);
    FindItems(p, "ProjectReference", refs);
    if (refs.Count > 0)
    {
        Console.WriteLine($"    References:");
        foreach (var r in refs) Console.WriteLine($"      - {r}");
    }
}

// Also try to find the source file contents from the binlog
void FindSourceFiles(BaseNode node, HashSet<string> files)
{
    if (node is SourceFile sf) files.Add(sf.Name);
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            FindSourceFiles(child, files);
}

Console.WriteLine("\n=== PROJECT FILE CONTENTS (from eval) ===");
foreach (var p in projects)
{
    // Try to find property values
    void FindProps(BaseNode n, Dictionary<string, string> props)
    {
        if (n is Property prop) props[prop.Name] = prop.Value;
        if (n is TreeNode tn2)
            foreach (var child in tn2.Children)
                FindProps(child, props);
    }
    var props = new Dictionary<string, string>();
    FindProps(p, props);
    if (props.ContainsKey("TargetFramework"))
        Console.WriteLine($"  {p.Name} TargetFramework: {props["TargetFramework"]}");
}
CSHARP

