using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Dump tree structure for one project to understand the node types
void DumpTree(BaseNode node, int depth, int maxDepth)
{
    if (depth > maxDepth) return;
    var indent = new string(' ', depth * 2);
    var text = node.ToString();
    if (text != null && text.Length > 200) text = text.Substring(0, 200);
    Console.WriteLine($"{indent}{node.GetType().Name}: {text}");
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            DumpTree(child, depth + 1, maxDepth);
}

// Find first Services.csproj project
void FindFirst(BaseNode node, ref Project found)
{
    if (found != null) return;
    if (node is Project p && p.Name == "Services.csproj") { found = p; return; }
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            FindFirst(child, ref found);
}

Project proj = null;
FindFirst(build, ref proj);
if (proj != null)
{
    Console.WriteLine("=== Services.csproj tree (depth 4) ===");
    DumpTree(proj, 0, 4);
}
