using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Find all project evaluations to get full properties and items
void FindAll(BaseNode node, Action<BaseNode> action)
{
    action(node);
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            FindAll(child, action);
}

// Find project with actual build (not just restore)
var projects = new List<Project>();
FindAll(build, n => { if (n is Project p) projects.Add(p); });

