var buildProjects = projects.Where(p => p.Name.EndsWith(".csproj")).ToList();

Console.WriteLine($"Total project evaluations: {buildProjects.Count}");

// For Services.csproj - find the evaluation that has the Csc target or Compile items
foreach (var p in buildProjects.Where(p => p.Name == "Services.csproj"))
{
    Console.WriteLine($"\n=== {p.Name} (Targets: {string.Join(",", p.Children.OfType<Target>().Select(t => t.Name).Take(20))}) ===");

    // Find all properties
    var props = new Dictionary<string, string>();
    FindAll(p, n => { if (n is Property prop) props[prop.Name] = prop.Value; });

    // Show interesting props
    foreach (var key in new[] { "TargetFramework", "RootNamespace", "AssemblyName" })
        if (props.ContainsKey(key)) Console.WriteLine($"  {key} = {props[key]}");

    // Find all AddItem nodes
    var items = new Dictionary<string, HashSet<string>>();
    FindAll(p, n =>
    {
        if (n is AddItem ai)
        {
            if (!items.ContainsKey(ai.Name)) items[ai.Name] = new();
            foreach (var child in ai.Children)
                if (child is Item item) items[ai.Name].Add(item.Text);
        }
    });

    foreach (var key in new[] { "PackageReference", "ProjectReference", "Compile", "Reference" })
    {
        if (items.ContainsKey(key))
        {
            Console.WriteLine($"  {key}:");
            foreach (var v in items[key]) Console.WriteLine($"    - {v}");
        }
    }
}
