using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Extract embedded files from binlog  
var archives = build.SourceFilesArchive;
if (archives != null)
{
    Console.WriteLine("=== EMBEDDED FILES ===");
    foreach (var entry in archives)
    {
        Console.WriteLine($"\n--- {entry.Key} ---");
        Console.WriteLine(entry.Value);
    }
}
else
{
    Console.WriteLine("No SourceFilesArchive found, trying alternate approach...");

    // Try to read the raw binlog for embedded content
    var reader = new BinLogReader();
    foreach (var record in reader.ReadRecords(binlogPath))
