using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

void FindAll(BaseNode node, Action<BaseNode> action)
{
    action(node);
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            FindAll(child, action);
}

// Dump all node types to understand structure
var types = new System.Collections.Generic.Dictionary<string, int>();
FindAll(build, n => {
    var t = n.GetType().Name;
    types.TryGetValue(t, out var c);
    types[t] = c + 1;
});

Console.WriteLine("=== Node type counts ===");
foreach (var kv in types.OrderByDescending(x => x.Value))
    Console.WriteLine($"  {kv.Key}: {kv.Value}");

// Look for any type that might contain file content
FindAll(build, n =>
{
    if (n.GetType().Name.Contains("Archive") || n.GetType().Name.Contains("Source") || n.GetType().Name.Contains("Embed"))
        Console.WriteLine($"[{n.GetType().Name}] {n}");
});

// Also check the build's SourceFiles property via reflection
var sfProp = build.GetType().GetProperty("SourceFiles");
if (sfProp != null)
{
    Console.WriteLine("\nSourceFiles property found!");
    var val = sfProp.GetValue(build);
    Console.WriteLine($"Type: {val?.GetType().FullName}");
}
